import { useState, KeyboardEvent } from 'react';
import { JxInputField, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  label?: string;
  placeholder?: string;
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultTags = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);
  const [draft, setDraft] = useState('');

  const commit = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      const value = draft.trim();
      if (value.length === 0) return;
      if (tags.includes(value)) {
        setDraft('');
        return;
      }
      commit([...tags, value]);
      setDraft('');
      return;
    }
    if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
      commit(tags.slice(0, -1));
    }
  };

  const removeTag = (index: number) => {
    commit(tags.filter((_, i) => i !== index));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-sm, 8px)' }}>
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        helperText="Enter — добавить тег, Backspace на пустом поле — удалить последний"
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-xs, 4px)' }}>
          {tags.map((tag, index) => (
            <JxChip key={tag} removable onRemove={() => removeTag(index)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

